    def _build_workspace(self):
        self.work_split = QSplitter(Qt.Orientation.Horizontal)
        self.work_split.addWidget(self._build_tree())
        self.work_split.addWidget(self._build_right())
        self.work_split.setStretchFactor(0, 45)
        self.work_split.setStretchFactor(1, 55)
        self.work_split.setSizes([620, 760])
