        self.cards_layout.addStretch(1)
        self.cards_area.setWidget(self.cards_host)
        self.cards_area.setMinimumHeight(84)
        self.right_split.addWidget(self.cards_area)

        self.preview = QStackedWidget()

        self.diff_view = QPlainTextEdit()
